    return try FfiConverterTypeGroup.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeGroup_lower(_ value: Group) -> UnsafeMutableRawPointer {
    return FfiConverterTypeGroup.lower(value)
