public struct ArchivedMessage {
    public var content: Data
    public var senderIndex: UInt32
    public var generation: UInt32
    public var epoch: UInt64
    public var aad: Data
    public var ownMessage: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(content: Data, senderIndex: UInt32, generation: UInt32, epoch: UInt64, aad: Data, ownMessage: Bool) {
        self.content = content
        self.senderIndex = senderIndex
        self.generation = generation
        self.epoch = epoch
        self.aad = aad
        self.ownMessage = ownMessage
    }
}



